{
  "criteria": [
    { "id": "task-points", "score": 26, "max": 30, "comment": "All four points are covered: name (\"Меня зовут Митч\"), where you live (\"в Колорадо\"), work (\"в компания\") and hobby (\"читать книга\"). Each point gets only one bare sentence, and the work point is vague because it does not say what company or what job." },
    { "id": "task-length", "score": 3, "max": 15, "comment": "There are only 4 real sentences against the required minimum of 10, and \"Пока.\" is a sign-off, not a sentence. There are no questions at all, but the task requires 2–5." },
    { "id": "letter-form", "score": 3, "max": 10, "comment": "There is no greeting, such as \"Привет, …!\", and no signature line. The text reads more like a list of facts than a letter to a friend. The closing \"Пока.\" earns some credit." },
    { "id": "vocabulary", "score": 12, "max": 20, "comment": "The words chosen (живу, невеста, компания, люблю читать) are correct and appropriate for A1. The range is very narrow because the letter is so short." },
    { "id": "grammar", "score": 14, "max": 25, "comment": "Three of the four sentences contain errors, and \"Пока.\" is error-free. The verb is left in the infinitive (\"Я работать\" instead of \"работаю\"). The instrumental after \"с\" is wrong (\"с моя невеста\"), as is the prepositional after \"в\" (\"в компания\"). The accusative after \"читать\" is missing (\"книга\"). Meaning stays clear, but these are basic forms." }
  ],
  "corrected": "Меня зовут Митч. Я живу в Колорадо с моей невестой. Я работаю в компании. Я люблю читать книги. Пока.",
  "changes": [
    { "before": "с моя невеста", "after": "с моей невестой", "explanation": "The preposition \"с\" (with) takes the instrumental case. Feminine \"моя невеста\" becomes \"моей невестой\"." },
    { "before": "Я работать", "after": "Я работаю", "explanation": "Verb conjugation: after \"я\" use the first-person singular present form \"работаю\", not the infinitive." },
    { "before": "в компания", "after": "в компании", "explanation": "\"В\" meaning location (where?) takes the prepositional case. Nouns ending in -ия change to -ии." },
    { "before": "читать книга", "after": "читать книги", "explanation": "The direct object of \"читать\" goes in the accusative case. When you talk about reading in general, use the plural \"книги\"." }
  ],
  "tips": [
    "Count before you finish: write at least 10 sentences and include 2–5 questions to your friend, e.g. \"Как ты живёшь?\", \"Где ты работаешь?\", \"Что ты любишь делать?\"",
    "Give it a letter shape. Start with \"Привет, [name]!\" and end with \"Пока!\" plus your name on its own line, e.g. \"Твой друг Митч\".",
    "Always conjugate verbs after a pronoun (я работаю, я живу), and change the noun ending after prepositions: в + prepositional (в компании), с + instrumental (с невестой)."
  ]
}
